from base import *
ev = lambda t,name,btn,now=False: f'''<div class="tile" style="flex:1;height:104px;display:flex;flex-direction:column;justify-content:space-between">
<div><div style="font-size:12px" class="s">{t}{' &nbsp;<span style="color:#fff">● now</span>' if now else ''}</div><div style="font-size:15px;font-weight:600;margin-top:3px">{name}</div></div><div>{btn}</div></div>'''
body = cap("Compact · 9 minutes before the next meeting") + compact('<span class="ring" style="--p:70%"></span><span>9m</span>','<span>Design sync</span>')
body += cap("Peek · one minute before (Join right there)") + compact('<span class="ring" style="--p:95%"></span><span>1m</span>','<span>Design sync</span>', peek='<span>Design sync · starts in 1 min</span><span class="pill main" style="height:18px">Join Meet</span>', h_scene=96)
inner = '<div style="display:flex;justify-content:space-between;margin-bottom:10px;font-size:13px"><b>Today</b><span class="q">Fri, Nov 20 · 3 left</span></div><div style="display:flex;gap:10px">' + ev("10:00 – 10:30","Design sync",'<span class="pill main">Join Meet</span>',True)+ev("13:30 – 14:00","1:1 with Alex",'<span class="pill">Join Zoom</span>')+ev("16:00 – 17:00","Dentist",'<span class="s" style="font-size:12px">123 Main St</span>') + '</div>'
body += cap("Open notch · Calendar page") + opened(inner, tabs='<span>♫</span><span>▤</span><span class="on">▦</span><span>⏱</span>')
h = '<div class="row">'+''.join(f'<div class="tile" style="background:#000;width:{w}px;height:{hh}px">{c}</div>' for w,hh,c in [
 (130,104,'<div class="q" style="font-size:11px">NEXT</div><div style="font-size:14px;font-weight:600;margin-top:4px">Design sync</div><div class="s" style="font-size:12px;margin-top:2px">in 9 min</div><div class="pill main" style="margin-top:12px;height:20px">Join</div>'),
 (270,104,'<div class="q" style="font-size:11px">NEXT EVENT</div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:6px"><div><div style="font-size:15px;font-weight:600">Design sync</div><div class="s" style="font-size:12px">10:00 · Google Meet</div></div><span class="ring" style="--p:70%;width:30px;height:30px;-webkit-mask:radial-gradient(circle,transparent 11px,#000 11.5px)"></span></div><div class="pill main" style="margin-top:10px;height:20px">Join</div>'),
 (270,104,'<div class="q" style="font-size:11px">AGENDA</div>'+''.join(f'<div style="display:flex;justify-content:space-between;font-size:12px;margin-top:5px"><span>{a}</span><span class="s">{b}</span></div>' for a,b in [("Design sync","10:00"),("1:1 with Alex","13:30"),("Dentist","16:00")]))])+'</div>'
body += cap("Home widgets · Next Event (small, medium) and Agenda") + h
open("m01.html","w").write(page("Calendar: next meeting beside the notch, with one-click Join","Countdown ring in the spot beside the notch, a Join peek, and today’s events in the open notch.",body))
